import java.io.*;
import java.util.*;

public class VanyaAndScaleVariant3 {
    static long[] a;
    static boolean isPossible;
    static int size;
    static long leftSum, rightSum;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long w = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long limit = (long) 1e11;
        a = new long[40];
        int count = 1;
        long val = 1;
        a[0] = 1;
        if (w <= 3) {
            System.out.println("YES");
            return;
        }
        for (int i = 1; i < 16; i++) {
            a[count] = val * w;
            val *= w;
            if (val > limit) break;
            count++;
        }
        leftSum = 0;
        rightSum = m;
        size = count;
        isPossible = false;
        dfs(0);
        System.out.println(isPossible ? "YES" : "NO");
    }

    static void dfs(int idx) {
        if (idx == size) {
            if (leftSum == rightSum) {
                isPossible = true;
            }
            return;
        }
        if (isPossible) return;
        for (int option = 0; option < 3; option++) {
            if (isPossible) return;
            switch (option) {
                case 1:
                    leftSum += a[idx];
                    dfs(idx + 1);
                    leftSum -= a[idx];
                    break;
                case 2:
                    rightSum += a[idx];
                    dfs(idx + 1);
                    rightSum -= a[idx];
                    break;
                default:
                    dfs(idx + 1);
            }
        }
    }
}
